{{-- optimistic-ui: n/a — sub-component
     The image inside tire-label, which draws a class and changes nothing. --}}
{{-- The image of one tire-label arrow, left to right: the arrow pointing left in the color of the
     class, with the class centered in the rectangular part, the range of the classes in black on
     white, the parameter's pictogram, and the decibels after the loudspeaker. Hidden from assistive
     technology, which the link's words serve. Laid out left to right whatever the page's direction.
     Expects $tireParameter (fuel, grip or noise), $tireClasses (best first), $tireClass,
     $tireStep, $tireSize and $tireDecibels (a number or null). --}}
<span class="wk-energy-image wk-tire-image {{ $tireSize }}" data-wk-tire="{{ $tireParameter }}" data-wk-tire-step="{{ $tireStep }}" dir="ltr" aria-hidden="true"><span class="wk-energy-arrow"><span class="wk-energy-body"><span class="wk-energy-letter">{{ $tireClass }}</span></span><svg class="wk-energy-tip" viewBox="0 0 10 20" preserveAspectRatio="none" focusable="false"><polygon points="0,0 10,10 0,20"/><polyline points="0,0 10,10 0,20"/></svg></span><span class="wk-energy-range"><span>{{ $tireClasses[0] }}</span><svg viewBox="0 0 6 20" preserveAspectRatio="none" focusable="false"><path d="M3 1.5V18.5M1 3.5L3 1.5L5 3.5M1 16.5L3 18.5L5 16.5" fill="none" stroke="currentColor" stroke-width="1" vector-effect="non-scaling-stroke"/></svg><span>{{ $tireClasses[count($tireClasses) - 1] }}</span></span><span class="wk-tire-pictogram">@if($tireParameter === 'fuel')<svg viewBox="0 0 20 20" focusable="false"><path d="M3.5 17.5V3.5H11.5V17.5M2 17.5H13M5.5 5.5H9.5V9H5.5ZM11.5 8H13.5V14.5A1.5 1.5 0 0 0 16.5 14.5V7.5L14.5 5.5" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round" stroke-linecap="round"/></svg>@elseif($tireParameter === 'grip')<svg viewBox="0 0 20 20" focusable="false"><path d="M6 12.5H15A3 3 0 0 0 14.7 6.5A4.5 4.5 0 0 0 6.2 5.6A3.5 3.5 0 0 0 6 12.5ZM7 15L6 18M10.5 15L9.5 18M14 15L13 18" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round" stroke-linecap="round"/></svg>@else<svg viewBox="0 0 20 20" focusable="false"><path d="M2.5 7.5H5.5L9.5 4.5V15.5L5.5 12.5H2.5ZM12.5 7.5A3.5 3.5 0 0 1 12.5 12.5M14.5 5.5A6.5 6.5 0 0 1 14.5 14.5M16.5 3.5A9.5 9.5 0 0 1 16.5 16.5" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round" stroke-linecap="round"/></svg>@endif</span>@if($tireDecibels !== null)<span class="wk-tire-decibels">{{ $tireDecibels }} dB</span>@endif</span>
